  ];
  let oy = 3.02;
  obs.forEach(o => {
    s.addShape(pres.shapes.OVAL, { x: 5.9, y: oy + 0.04, w: 0.14, h: 0.14, fill: { color: C.teal }, line: { color: C.teal } });
    s.addText(o, {
