}

// ============================================================
// SLIDE 6 — Takeaways
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Top accent
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }, line: { color: C.teal } });

  // Right glow panel
