    s.addShape(pres.shapes.RECTANGLE, { x: 0.28, y: fy, w: 0.06, h: 0.78, fill: { color: C.teal }, line: { color: C.teal } });
    s.addText(f.num, { x: 0.38, y: fy + 0.04, w: 0.5, h: 0.28, fontFace: FONT_HEAD, fontSize: 16, bold: true, color: C.teal, margin: 0 });
    s.addText(f.head, { x: 0.9, y: fy + 0.04, w: 4.55, h: 0.26, fontFace: FONT_BODY, fontSize: 11, bold: true, color: C.white, margin: 0 });
    s.addText(f.body, { x: 0.9, y: fy + 0.3, w: 4.55, h: 0.4, fontFace: FONT_BODY, fontSize: 9, color: "9DC4E0", margin: 0 });
    fy += 0.88;
