    s.addText(r.prio, { x: 6.0, y: ry + 0.06, w: 1.6, h: 0.22, fontFace: FONT_BODY, fontSize: 8, bold: true, color: r.color, charSpacing: 1, margin: 0 });
    s.addText(r.model, { x: 6.0, y: ry + 0.28, w: 2.2, h: 0.38, fontFace: FONT_HEAD, fontSize: 13, bold: true, color: C.white, margin: 0 });
