"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "AI Model Landscape April 2026";
pres.author = "Artificial Analysis";

// --- Design tokens ---
const C = {
  navy:    "0F2044",  // dominant dark
  teal:    "0D9488",  // accent
  tealLt:  "14B8A6",  // lighter accent
  mint:    "CCFBF1",  // very light teal
  white:   "FFFFFF",
  offWht:  "F8FAFC",
  slate:   "64748B",
  slateD:  "334155",
  sky:     "E0F2FE",
  gold:    "F59E0B",
  goldLt:  "FEF3C7",
};

const FONT_HEAD = "Georgia";
const FONT_BODY = "Calibri";

// helper: create shadow object fresh each call
const mkShadow = () => ({ type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 });

// ============================================================
// SLIDE 1 — Title
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Top teal accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.teal }, line: { color: C.teal } });

  // Diagonal decorative shape (right side)
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0, w: 3.2, h: 5.625,
    fill: { color: "0A1A36", transparency: 0 }, line: { color: "0A1A36" }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 0, w: 2.8, h: 5.625,
    fill: { color: "071330", transparency: 0 }, line: { color: "071330" }
  });

  // Teal circle accent
  s.addShape(pres.shapes.OVAL, {
    x: 7.6, y: 0.8, w: 1.8, h: 1.8,
    fill: { color: C.teal, transparency: 75 }, line: { color: C.teal, width: 2, transparency: 50 }
  });
  s.addShape(pres.shapes.OVAL, {
    x: 7.9, y: 1.1, w: 1.2, h: 1.2,
    fill: { color: C.teal, transparency: 60 }, line: { color: C.tealLt, width: 1 }
  });

  // Eyebrow
  s.addText("ARTIFICIAL ANALYSIS  •  APRIL 2026", {
    x: 0.5, y: 1.05, w: 5.8, h: 0.3,
    fontFace: FONT_BODY, fontSize: 10, color: C.tealLt, bold: true,
    charSpacing: 3, margin: 0
  });

  // Main title
  s.addText("AI Model Landscape\nApril 2026", {
    x: 0.5, y: 1.45, w: 6.0, h: 1.6,
    fontFace: FONT_HEAD, fontSize: 36, bold: true, color: C.white,
    lineSpacingMultiple: 1.15, margin: 0
  });

  // Subtitle
  s.addText("Benchmarking Intelligence, Speed, and Cost\nAcross 11 Frontier Models", {
    x: 0.5, y: 3.1, w: 5.8, h: 0.75,
    fontFace: FONT_BODY, fontSize: 16, color: "A0BFD8", margin: 0
  });

  // Bottom stat bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.05, w: 10, h: 0.575, fill: { color: "071330" }, line: { color: "071330" } });

  const stats = [
    { val: "11", lbl: "MODELS EVALUATED" },
    { val: "3",  lbl: "KEY DIMENSIONS" },
    { val: "33×", lbl: "PRICING SPREAD" },
    { val: "57",  lbl: "TOP INTELLIGENCE SCORE" },
  ];
  stats.forEach((st, i) => {
    const bx = 0.4 + i * 2.4;
    s.addText(st.val, { x: bx, y: 5.0, w: 1.6, h: 0.38, fontFace: FONT_HEAD, fontSize: 22, bold: true, color: C.tealLt, margin: 0 });
    s.addText(st.lbl, { x: bx, y: 5.35, w: 2.0, h: 0.2, fontFace: FONT_BODY, fontSize: 8, color: "7BAAC7", charSpacing: 1, margin: 0 });
  });

  // Source tag
  s.addText("Source: artificialanalysis.ai", {
    x: 7.0, y: 5.35, w: 2.7, h: 0.2,
    fontFace: FONT_BODY, fontSize: 9, color: C.slate, align: "right", margin: 0
  });
}

// ============================================================
// SLIDE 2 — Intelligence Index (bar chart + table)
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.offWht };

  // Left dark column header
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.teal }, line: { color: C.teal } });
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.navy }, line: { color: C.navy } });

  s.addText("Gemini 3.1 Pro Preview and GPT-5.4 Co-Lead the Intelligence Index at 57", {
    x: 0.22, y: 0.0, w: 9.5, h: 0.72,
    fontFace: FONT_HEAD, fontSize: 17, bold: true, color: C.white, valign: "middle", margin: 0
  });

  // Bar chart (horizontal)
  const models = [
    "Gemini 3.1 Pro Preview",
    "GPT-5.4 (xhigh)",
    "Claude Opus 4.6 (max)",
    "Muse Spark",
    "Claude Sonnet 4.6 (max)",
    "GLM-5.1",
    "Grok 4.20 0309 v2",
    "Gemini 3 Flash",
    "DeepSeek V3.2",
    "NVIDIA Nemotron 3 Super",
    "gpt-oss-120B (high)",
  ];
  const scores = [57, 57, 53, 52, 52, 51, 49, 46, 42, 36, 33];
  const providers = ["Google","OpenAI","Anthropic","Meta","Anthropic","Z AI","xAI","Google","DeepSeek","NVIDIA","OpenAI"];

  // Color: top 2 = teal, open-weight = gold, rest = navy
  const openWeight = new Set([5, 6, 8, 9, 10]);
  const barColors = scores.map((_, i) => {
    if (i < 2) return C.teal;
    if (openWeight.has(i)) return C.gold;
    return "2563EB";
  });

  s.addChart(pres.charts.BAR, [{
    name: "Intelligence Index",
    labels: models,
    values: scores,
  }], {
    x: 0.12, y: 0.75, w: 5.6, h: 4.7,
    barDir: "bar",
    chartColors: barColors,
    chartArea: { fill: { color: C.offWht } },
    plotArea: { fill: { color: C.offWht } },
    catAxisLabelColor: C.slateD,
    catAxisFontSize: 9,
    valAxisLabelColor: C.slate,
    valAxisFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.slateD,
    dataLabelFontSize: 9,
    valAxisMinVal: 0,
    valAxisMaxVal: 65,
    showLegend: false,
  });

  // Right side: summary table
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.85, y: 0.75, w: 3.95, h: 4.7,
    fill: { color: C.white }, line: { color: "E2E8F0", width: 1 },
    shadow: mkShadow()
  });

  s.addText("Full Rankings", {
    x: 5.95, y: 0.82, w: 3.75, h: 0.3,
    fontFace: FONT_HEAD, fontSize: 13, bold: true, color: C.navy, margin: 0
  });

  // Table header
  const tblData = [
    [
      { text: "#",     options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
      { text: "Model", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9 } },
      { text: "Provider", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9 } },
      { text: "Score",  options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
    ],
  ];
  models.forEach((m, i) => {
    const isTop = i < 2;
    const isOW = openWeight.has(i);
    const rowFill = isTop ? C.mint : (i % 2 === 0 ? C.white : C.offWht);
    const scoreColor = isTop ? C.teal : (isOW ? "B45309" : C.slateD);
    tblData.push([
      { text: String(i + 1),    options: { fontSize: 8, align: "center", fill: { color: rowFill }, color: C.slate } },
      { text: m,                options: { fontSize: 8, fill: { color: rowFill }, color: C.slateD, bold: isTop } },
      { text: providers[i],     options: { fontSize: 8, fill: { color: rowFill }, color: C.slate } },
      { text: String(scores[i]),options: { fontSize: 9, align: "center", fill: { color: rowFill }, color: scoreColor, bold: isTop || isOW } },
    ]);
  });

  s.addTable(tblData, {
    x: 5.9, y: 1.17, w: 3.85,
    colW: [0.32, 1.88, 0.92, 0.73],
    border: { pt: 0.5, color: "E2E8F0" },
  });

  // Legend
  s.addShape(pres.shapes.RECTANGLE, { x: 5.9, y: 5.22, w: 0.18, h: 0.12, fill: { color: C.teal }, line: { color: C.teal } });
  s.addText("Co-leaders", { x: 6.12, y: 5.2, w: 1.0, h: 0.16, fontFace: FONT_BODY, fontSize: 8, color: C.slate, margin: 0 });
  s.addShape(pres.shapes.RECTANGLE, { x: 7.2, y: 5.22, w: 0.18, h: 0.12, fill: { color: C.gold }, line: { color: C.gold } });
  s.addText("Open-weight", { x: 7.42, y: 5.2, w: 1.2, h: 0.16, fontFace: FONT_BODY, fontSize: 8, color: C.slate, margin: 0 });

  s.addText("Source: artificialanalysis.ai", {
    x: 0.15, y: 5.42, w: 4, h: 0.18,
    fontFace: FONT_BODY, fontSize: 8, color: C.slate, margin: 0
  });
}

// ============================================================
// SLIDE 3 — Speed
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.offWht };

  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.08, h: 5.625, fill: { color: C.gold }, line: { color: C.gold } });
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.72, fill: { color: C.navy }, line: { color: C.navy } });

  s.addText("gpt-oss-120B Tops Output Speed at 218 Tokens/s — More Than 4× Faster Than Claude Opus 4.6", {
    x: 0.22, y: 0.0, w: 9.5, h: 0.72,
    fontFace: FONT_HEAD, fontSize: 15, bold: true, color: C.white, valign: "middle", margin: 0
  });

  const speedModels = [
    "gpt-oss-120B (high)",
    "Grok 4.20 0309 v2",
    "NVIDIA Nemotron 3 Super",
    "Gemini 3 Flash",
    "Gemini 3.1 Pro Preview",
    "GPT-5.4 (xhigh)",
    "GLM-5.1",
    "Claude Sonnet 4.6 (max)",
    "Claude Opus 4.6 (max)",
    "DeepSeek V3.2",
  ];
  const speeds = [218, 188, 172, 153, 118, 83, 64, 63, 49, 46];
  const openWeightSpeed = new Set([0, 1, 2, 6, 9]);

  const speedColors = speeds.map((_, i) => {
    if (i === 0) return C.gold;
    if (openWeightSpeed.has(i)) return "F59E0B";
    return "2563EB";
  });

  s.addChart(pres.charts.BAR, [{
    name: "Output Tokens/s",
    labels: speedModels,
    values: speeds,
  }], {
    x: 0.12, y: 0.78, w: 6.2, h: 4.65,
    barDir: "bar",
    chartColors: speedColors,
    chartArea: { fill: { color: C.offWht } },
    plotArea: { fill: { color: C.offWht } },
    catAxisLabelColor: C.slateD,
    catAxisFontSize: 9,
    valAxisLabelColor: C.slate,
    valAxisFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.slateD,
    dataLabelFontSize: 9,
    showLegend: false,
  });

  // Right: key insights
  const insights = [
    { icon: "⚡", head: "218 tokens/s", body: "gpt-oss-120B sets the pace — 4× faster than Claude Opus 4.6 (49 t/s)" },
    { icon: "↕", head: "Inverse relationship", body: "The two smartest models (Gemini 3.1 Pro, GPT-5.4) hit only 118 and 83 t/s" },
    { icon: "✦", head: "Open-weight advantage", body: "4 of the top 5 fastest are open-weight or smaller-parameter models" },
    { icon: "💰", head: "Speed ≠ intelligence", body: "Latency-sensitive workloads can pick fast/cheap models without sacrificing throughput" },
  ];

  let iy = 0.85;
  insights.forEach(ins => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.5, y: iy, w: 3.3, h: 0.95,
      fill: { color: C.white }, line: { color: "E2E8F0", width: 1 }, shadow: mkShadow()
    });
    s.addShape(pres.shapes.OVAL, {
      x: 6.58, y: iy + 0.22, w: 0.42, h: 0.42,
      fill: { color: C.goldLt }, line: { color: C.gold, width: 1 }
    });
    s.addText(ins.icon, { x: 6.57, y: iy + 0.18, w: 0.44, h: 0.42, fontFace: FONT_BODY, fontSize: 12, align: "center", color: "92400E", margin: 0 });
    s.addText(ins.head, { x: 7.05, y: iy + 0.06, w: 2.65, h: 0.26, fontFace: FONT_BODY, fontSize: 11, bold: true, color: C.navy, margin: 0 });
    s.addText(ins.body, { x: 7.05, y: iy + 0.32, w: 2.65, h: 0.52, fontFace: FONT_BODY, fontSize: 9, color: C.slateD, margin: 0 });
    iy += 1.08;
  });

  s.addText("Source: artificialanalysis.ai  •  Muse Spark excluded (no speed data published)", {
    x: 0.15, y: 5.42, w: 8, h: 0.18,
    fontFace: FONT_BODY, fontSize: 8, color: C.slate, margin: 0
  });
}

// ============================================================
// SLIDE 4 — Pricing
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.offWht };

